                rr,cc=r+dr,c+dc
                while 0<=rr<H and 0<=cc<W:
                    v=orig[rr,cc]
                    if v==mark: out[rr,cc]=4; break
                    if v==bg: out[rr,cc]=fill; rr+=dr; cc+=dc
                    elif v!=wall: break
    return out.tolist()
